import{_ as i,c as a,o as t,aj as h}from"./chunks/framework.BZUl9-wD.js";const c=JSON.parse('{"title":"安装指南","description":"Torch-RecHub 详细安装说明，包括稳定版和最新版安装步骤","frontmatter":{"title":"安装指南","description":"Torch-RecHub 详细安装说明，包括稳定版和最新版安装步骤"},"headers":[],"relativePath":"zh/guide/install.md","filePath":"zh/guide/install.md"}'),n={name:"zh/guide/install.md"};function e(l,s,p,r,d,k){return t(),a("div",null,[...s[0]||(s[0]=[h(`<h1 id="安装指南" tabindex="-1">安装指南 <a class="header-anchor" href="#安装指南" aria-label="Permalink to “安装指南”">​</a></h1><p>本文档提供了 Torch-RecHub 的详细安装说明，包括稳定版和最新开发版的安装步骤。</p><h2 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to “系统要求”">​</a></h2><ul><li>Python 3.10 及以上</li><li>PyTorch <code>&gt;=2.6,&lt;3</code></li></ul><p>NumPy（1.26.4+）、pandas（2.1+）和 scikit-learn（1.4+）会随项目安装。生成式模型使用可选依赖 Transformers（<code>&gt;=4.57.3,&lt;5</code>）。</p><h2 id="安装方式" tabindex="-1">安装方式 <a class="header-anchor" href="#安装方式" aria-label="Permalink to “安装方式”">​</a></h2><p>CPU 环境可直接选择稳定版或源码安装。使用 GPU 或 NPU 时，先按<a href="#按设备安装-pytorch">设备示例</a>准备 PyTorch，再在同一个环境中安装 Torch-RecHub。</p><h3 id="稳定版-推荐用户使用" tabindex="-1">稳定版（推荐用户使用） <a class="header-anchor" href="#稳定版-推荐用户使用" aria-label="Permalink to “稳定版（推荐用户使用）”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch-rechub</span></span></code></pre></div><h3 id="可选功能" tabindex="-1">可选功能 <a class="header-anchor" href="#可选功能" aria-label="Permalink to “可选功能”">​</a></h3><p>默认安装只包含核心训练依赖。按实际用途选择 extra：使用发布包时执行表中的 pip 命令；使用源码时，在仓库根目录运行 <code>uv sync --extra &lt;name&gt;</code>，例如 <code>uv sync --extra visualization</code>。</p><table tabindex="0"><thead><tr><th>用途</th><th>安装命令</th></tr></thead><tbody><tr><td>生成式模型</td><td><code>python -m pip install &quot;torch-rechub[generative]&quot;</code></td></tr><tr><td>Parquet 流式数据</td><td><code>python -m pip install &quot;torch-rechub[bigdata]&quot;</code></td></tr><tr><td>ONNX 导出与量化</td><td><code>python -m pip install &quot;torch-rechub[onnx]&quot;</code></td></tr><tr><td>模型可视化</td><td><code>python -m pip install &quot;torch-rechub[visualization]&quot;</code></td></tr><tr><td>实验跟踪</td><td><code>python -m pip install &quot;torch-rechub[tracking]&quot;</code></td></tr><tr><td>向量检索</td><td><code>python -m pip install &quot;torch-rechub[annoy]&quot;</code>（按后端选 <code>annoy</code>、<code>faiss</code> 或 <code>milvus</code>）</td></tr><tr><td>测试、格式化与类型检查工具</td><td><code>python -m pip install &quot;torch-rechub[dev]&quot;</code></td></tr><tr><td>全部可选功能</td><td><code>python -m pip install &quot;torch-rechub[all]&quot;</code></td></tr></tbody></table><p>渲染模型结构图还需在系统中安装 Graphviz，并确保命令行能找到 <code>dot</code>。</p><p>运行脚本时，也可用 <code>uv run --extra &lt;name&gt; python &lt;script.py&gt;</code> 指定所需依赖组；多个依赖组可以重复传入 <code>--extra</code>。</p><h3 id="最新开发版" tabindex="-1">最新开发版 <a class="header-anchor" href="#最新开发版" aria-label="Permalink to “最新开发版”">​</a></h3><p>要安装包含最新功能的开发版本：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 首先安装 uv（如果尚未安装）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uv</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 克隆并安装</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/datawhalechina/torch-rechub.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch-rechub</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 创建 .venv、安装锁定依赖，并以可编辑方式安装当前项目</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span></span></code></pre></div><p>已按设备安装 PyTorch 时，最后一步用 <code>uv pip install -e .</code> 将源码装到当前已激活的环境中，再用该环境的 <code>python</code> 运行示例。</p><h2 id="开发环境设置" tabindex="-1">开发环境设置 <a class="header-anchor" href="#开发环境设置" aria-label="Permalink to “开发环境设置”">​</a></h2><p>如果您想为 Torch-RecHub 做出贡献或使用源代码：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Fork 并克隆仓库</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/YOUR_USERNAME/torch-rechub.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch-rechub</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 安装依赖并设置环境</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. 运行测试（uv sync 已以可编辑方式安装当前项目）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span></span></code></pre></div><h2 id="按设备安装-pytorch" tabindex="-1">按设备安装 PyTorch <a class="header-anchor" href="#按设备安装-pytorch" aria-label="Permalink to “按设备安装 PyTorch”">​</a></h2><p>NVIDIA GPU 按显卡和驱动选择 CUDA 版 PyTorch，AMD GPU 按显卡型号选择 ROCm 版 PyTorch，华为昇腾 NPU 先安装并加载 CANN，再选择配套的 PyTorch 和 <code>torch-npu</code>。具体组合可查阅 <a href="https://pytorch.org/get-started/locally/" target="_blank" rel="noreferrer">PyTorch 安装向导</a>、<a href="https://rocm.docs.amd.com/projects/radeon-ryzen/en/latest/" target="_blank" rel="noreferrer">AMD ROCm 文档</a> 和<a href="https://github.com/Ascend/pytorch/blob/master/COMPATIBILITY.md" target="_blank" rel="noreferrer">昇腾版本配套表</a>。</p><p>在已激活的 Python 环境中，按设备选择一条安装命令。使用 uv 时，可将 <code>python -m pip</code> 换成 <code>uv pip</code>。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># CPU（Linux 或 Windows 的纯 CPU 版本）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --index-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://download.pytorch.org/whl/cpu</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># NVIDIA GPU，以 CUDA 12.6 为例</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --index-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://download.pytorch.org/whl/cu126</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># AMD GPU，以 Ryzen AI Max+ 395（gfx1151）为例</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --index-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://repo.amd.com/rocm/whl/gfx1151/</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;rocm[libraries,devel]&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torchvision</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torchaudio</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 华为昇腾 NPU，默认包版本与本机 CANN 匹配时</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch-npu</span></span></code></pre></div><p>使用第一张卡训练时，NVIDIA 和 AMD 在 Trainer 中都写 <code>device=&quot;cuda:0&quot;</code>，华为昇腾可在导入 <code>torch_npu</code> 后使用 <code>device=&quot;npu:0&quot;</code>。</p><h2 id="验证安装" tabindex="-1">验证安装 <a class="header-anchor" href="#验证安装" aria-label="Permalink to “验证安装”">​</a></h2><p>在安装 Torch-RecHub 的环境中查看版本。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import torch_rechub; print(torch_rechub.__version__)&quot;</span></span></code></pre></div><h2 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to “故障排除”">​</a></h2><h3 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h3><p>如果您遇到任何安装问题，请：</p><ol><li>查看 <a href="https://github.com/datawhalechina/torch-rechub/issues" target="_blank" rel="noreferrer">GitHub Issues</a></li><li>创建新的 Issue，并提供详细的错误信息和系统信息</li><li>参考 <a href="/torch-rechub/zh/community/faq.html">常见问题解答</a></li></ol>`,33)])])}const F=i(n,[["render",e]]);export{c as __pageData,F as default};
